contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address token, address[] memory tos, uint[] memory vals) public {
        require(tos.length == vals.length);
        bool reverted;
        bool ok;
        if (tos.length == 0) {
            try c.transfer(from, token, tos, vals) returns (bool r) {
                reverted = false;
                ok = r;
            } catch {
                reverted = true;
                ok = false;
            }
        } else {
            ok = c.transfer(from, token, tos, vals);
            reverted = false;
        }
        if (tos.length == 0) {
            assert(reverted);
        } else {
            assert(!reverted && ok);
        }
    }
    receive() external payable {}
}

